{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "It would require each local board of education to establish school lunch and breakfast programs that provide free meals to eligible students.",
      "rationale": "Conveys the board mandate and both meal programs, but does not specify that all enrolled students eligible for either free or reduced-price meals must receive free meals."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "If funding is available, the state would reimburse local education agencies for the cost of providing free breakfast and lunch to students eligible for reduced-price meals, after all available federal funds have been used.",
      "rationale": "Conveys state reimbursement, the funding condition, both meals, the reduced-price eligibility limitation, and exhaustion of available federal funds."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "The bill also removes specific language from Tennessee Code Annotated Section 49-6-2303",
      "rationale": "Identifies a language deletion in the correct section, but omits subdivision (5) and the deleted phrase, which are needed to identify the amendment precisely."
    },
    {
      "proposition_id": "P4",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The general reference to removing language does not convey the separate deletion of § 49-6-2303(10)."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "updates the wording in Section 49-2-114(a) to refer to household income eligibility for free or reduced-price lunch based on federal standards.",
      "rationale": "Identifies the amended provision and conveys the new household-income eligibility criterion under federal standards; quoting the replaced wording is unnecessary."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "If passed, these changes would take effect July 1, 2025, and apply to the 2025-2026 school year and beyond.",
      "rationale": "Conveys the effective date and application to the specified school year and subsequent years."
    }
  ]
}
